<?php
$items=$cameras??[];$groups=[];
foreach($items as $camera){$area=trim((string)($camera['area']??''));if($area==='')$area='Área general';$groups[$area][]=$camera;}
uksort($groups,static fn(string $a,string $b):int=>strnatcasecmp($a,$b));
?>
<section class="resident-page-title"><span>Videovigilancia</span><h1>Cámaras</h1><p>Cámaras autorizadas, organizadas por zona o área.</p></section>
<?php foreach($groups as $areaName=>$groupItems):?>
<section class="resident-resource-group"><div class="resident-resource-group-title"><i class="bi bi-geo-alt"></i><div><strong><?=e($areaName)?></strong><small><?=count($groupItems)?> cámara(s)</small></div></div><section class="camera-grid-mobile">
<?php foreach($groupItems as $camera):$hasSnapshot=!empty($camera['snapshot_path']);$live=!empty($camera['live_enabled'])&&(string)($camera['live_status']??'')==='ready';$displayName=(string)($camera['resident_display_name']??$camera['resident_name']??$camera['name']);?>
<article>
  <div class="camera-mobile-preview" style="overflow:hidden;position:relative">
    <?php if($hasSnapshot):?><img src="<?=url('camera-snapshot',['id'=>$camera['id'],'v'=>strtotime((string)($camera['snapshot_at']??'now'))])?>" alt="<?=e($displayName)?>" style="width:100%;height:100%;min-height:125px;object-fit:cover"><?php else:?><i class="bi bi-camera-video-fill"></i><?php endif;?>
    <span class="camera-status status-<?=e($camera['status'])?>"></span><?php if($live):?><span class="badge text-bg-success" style="position:absolute;left:8px;top:8px"><i class="bi bi-broadcast"></i> EN VIVO</span><?php endif;?>
  </div>
  <div><strong><?=e($displayName)?></strong><small><?=e($camera['brand'])?></small><span><?=e(status_label((string)$camera['status']))?><?php if(!empty($camera['live_codec'])):?> · <?=e((string)$camera['live_codec'])?><?php endif;?></span></div>
  <?php if($live):?><button type="button" data-bs-toggle="modal" data-bs-target="#residentCameraModal" data-camera-id="<?=(int)$camera['id']?>" data-camera-name="<?=e($displayName)?>" data-live="1"><i class="bi bi-play-circle"></i> En vivo</button>
  <?php elseif($hasSnapshot):?><button type="button" data-bs-toggle="modal" data-bs-target="#residentCameraModal" data-camera-id="<?=(int)$camera['id']?>" data-camera-name="<?=e($displayName)?>" data-live="0">Ver imagen</button>
  <?php else:?><button disabled>Video pendiente</button><?php endif;?>
</article>
<?php endforeach;?></section></section>
<?php endforeach;?>
<?php if(!$items):?><div class="resident-empty">No hay cámaras autorizadas para esta cuenta.</div><?php endif;?>
<div class="safety-note"><i class="bi bi-shield-check"></i><p>El residente nunca recibe la IP local ni las credenciales ONVIF/RTSP. El Node valida permisos y entrega el video o imagen segura.</p></div>
<style>.resident-resource-group{margin-bottom:1rem}.resident-resource-group-title{display:flex;align-items:center;gap:.65rem;margin:0 0 .55rem;padding:.15rem .1rem}.resident-resource-group-title>i{font-size:1.05rem}.resident-resource-group-title strong{display:block}.resident-resource-group-title small{display:block;opacity:.65;font-size:.76rem}</style>

<div class="modal fade" id="residentCameraModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered modal-xl"><div class="modal-content resident-modal"><div class="modal-header"><div><strong id="residentCameraTitle">Cámara</strong><small id="residentCameraState">Preparando vista…</small></div><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body p-0 bg-dark text-center" style="min-height:300px;position:relative">
<video id="residentCameraVideo" muted autoplay playsinline controls style="width:100%;max-height:72vh;display:none;background:#000"></video>
<img id="residentCameraImage" alt="Vista de cámara" style="width:100%;max-height:72vh;object-fit:contain;display:none">
<div id="residentCameraLoading" class="text-white p-5"><span class="spinner-border spinner-border-sm me-2"></span>Conectando video…</div><button type="button" id="residentCameraPlay" class="btn btn-light position-absolute top-50 start-50 translate-middle" style="display:none;z-index:5"><i class="bi bi-play-fill me-1"></i>Reproducir video</button>
</div><div id="residentCameraAccessBar" class="border-top px-3 py-2 bg-body" style="display:none"><div class="d-flex flex-wrap align-items-center gap-2"><span class="small fw-semibold me-1"><i class="bi bi-door-open me-1"></i>Accesos asociados</span><div id="residentCameraAccessControls" class="d-flex flex-wrap gap-2"></div><small id="residentCameraAccessState" class="text-body-secondary ms-auto"></small></div></div><div class="modal-footer"><button type="button" class="resident-secondary-button" id="residentCameraRefresh"><i class="bi bi-arrow-clockwise"></i> Reintentar</button><button type="button" class="resident-primary-button" data-bs-dismiss="modal">Cerrar</button></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/hls.js@1.7.0/dist/hls.min.js" crossorigin="anonymous"></script>
<script src="<?=asset('assets/js/property-webrtc.js')?>"></script>
<script>
(()=>{const modal=document.getElementById('residentCameraModal'),video=document.getElementById('residentCameraVideo'),img=document.getElementById('residentCameraImage'),title=document.getElementById('residentCameraTitle'),state=document.getElementById('residentCameraState'),loading=document.getElementById('residentCameraLoading'),playBtn=document.getElementById('residentCameraPlay'),refresh=document.getElementById('residentCameraRefresh'),accessBar=document.getElementById('residentCameraAccessBar'),accessControls=document.getElementById('residentCameraAccessControls'),accessState=document.getElementById('residentCameraAccessState');let id=0,wantsLive=false,player=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const pollAccess=async(correlation,button)=>{for(let n=0;n<12;n++){await sleep(700);try{const r=await fetch('<?=url('camera-access-command-status')?>&correlation='+encodeURIComponent(correlation)+'&t='+Date.now(),{credentials:'same-origin',cache:'no-store'});const x=await r.json();if(!r.ok||!x.ok)continue;const st=String(x.status||'').toLowerCase();if(st==='confirmed'){button.classList.remove('btn-warning');button.classList.add('btn-success');button.innerHTML='<i class="bi bi-check2-circle me-1"></i>'+esc(x.access_name||button.dataset.label||'Abierto');accessState.textContent='Apertura confirmada · continúas viendo la cámara';setTimeout(()=>{button.classList.remove('btn-success');button.classList.add('btn-outline-success');button.innerHTML='<i class="bi bi-door-open me-1"></i>'+esc(button.dataset.label||x.access_name||'Acceso');button.disabled=false;},1800);return;}if(['failed','denied','timeout'].includes(st))throw new Error(x.error||'La apertura no fue confirmada.');}catch(err){if(n>=11){button.classList.remove('btn-warning');button.classList.add('btn-outline-danger');button.innerHTML='<i class="bi bi-exclamation-triangle me-1"></i>'+esc(button.dataset.label||'Acceso');button.disabled=false;accessState.textContent=err?.message||String(err);return;}}}button.classList.remove('btn-warning');button.classList.add('btn-outline-success');button.innerHTML='<i class="bi bi-door-open me-1"></i>'+esc(button.dataset.label||'Acceso');button.disabled=false;accessState.textContent='Comando enviado; confirmación pendiente.';};
const openAccess=async(point,button)=>{if(!point.can_open||button.disabled)return;button.disabled=true;button.classList.remove('btn-outline-success');button.classList.add('btn-warning');button.innerHTML='<span class="spinner-border spinner-border-sm me-1"></span>Abriendo '+esc(point.name);accessState.textContent='Enviando apertura sin detener el video…';try{const body=new URLSearchParams();body.set('_csrf',<?=json_encode(csrf_token(),JSON_UNESCAPED_SLASHES)?>);body.set('camera_id',String(id));body.set('access_point_id',String(point.id));const r=await fetch('<?=url('camera-access-open')?>',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:body.toString()});const x=await r.json();if(!r.ok||!x.ok)throw new Error(x.message||'No fue posible abrir.');accessState.textContent='Comando enviado · esperando confirmación';await pollAccess(x.correlation_uuid,button);}catch(err){button.classList.remove('btn-warning');button.classList.add('btn-outline-danger');button.innerHTML='<i class="bi bi-exclamation-triangle me-1"></i>'+esc(point.name);button.disabled=false;accessState.textContent=err?.message||String(err);}};
const loadAccess=async()=>{if(accessControls)accessControls.innerHTML='';if(accessBar)accessBar.style.display='none';if(accessState)accessState.textContent='';if(!id)return;try{const r=await fetch('<?=url('camera-associated-access')?>&camera_id='+encodeURIComponent(id)+'&t='+Date.now(),{credentials:'same-origin',cache:'no-store'});const x=await r.json();if(!r.ok||!x.ok||!Array.isArray(x.access_points)||!x.access_points.length)return;accessBar.style.display='';x.access_points.forEach(point=>{const b=document.createElement('button');b.type='button';b.className='btn btn-sm '+(point.can_open?'btn-outline-success':'btn-outline-secondary');b.disabled=!point.can_open;b.title=point.can_open?'Abrir mientras observa el video':(point.reason||'No disponible');b.dataset.label=String(point.name||'Acceso');b.innerHTML='<i class="bi bi-door-open me-1"></i>'+esc(point.name);b.addEventListener('click',()=>openAccess(point,b));accessControls.appendChild(b);});}catch(e){if(accessState)accessState.textContent='No se pudieron cargar los accesos asociados.';}};
const clientLog=(phase,message,extra={})=>{try{const data=new URLSearchParams();data.set('_csrf',<?=json_encode(csrf_token(),JSON_UNESCAPED_SLASHES)?>);data.set('source','resident-camera-player');data.set('phase',String(phase||'unknown'));data.set('message',String(message||'')+' '+JSON.stringify(extra||{}));data.set('url',location.href);fetch('<?=url('client-log')?>',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:data.toString(),keepalive:true}).catch(()=>{});}catch(e){}};
window.addEventListener('error',ev=>clientLog('window-error',ev.message||'window error',{camera_id:id,filename:ev.filename||'',line:ev.lineno||0}));window.addEventListener('unhandledrejection',ev=>clientLog('unhandled-rejection',String(ev.reason?.message||ev.reason||'promise rejected'),{camera_id:id}));
const snapshot=()=>{if(!id)return;video.style.display='none';loading.style.display='none';if(playBtn)playBtn.style.display='none';img.style.display='block';img.src='<?=url('camera-snapshot')?>&id='+encodeURIComponent(id)+'&t='+Date.now();state.textContent='Imagen segura recibida desde el Edge Agent';};
const connect=async()=>{if(!id)return;if(player)await player.close();img.style.display='none';video.style.display='none';loading.style.display='block';state.textContent='Solicitando video autorizado…';if(!wantsLive){snapshot();return;}clientLog('connect-start','Solicitando configuración',{camera_id:id,ua:navigator.userAgent,standalone:!!(window.matchMedia&&window.matchMedia('(display-mode: standalone)').matches)});try{const r=await fetch('<?=url('camera-live-config')?>&id='+encodeURIComponent(id)+'&t='+Date.now(),{credentials:'same-origin',cache:'no-store',redirect:'follow'});const ct=r.headers.get('content-type')||'';const raw=await r.text();let cfg={};try{cfg=JSON.parse(raw);}catch(parseError){throw new Error('La configuración de cámara no devolvió JSON (HTTP '+r.status+', '+ct+').');}clientLog('config-result','Configuración recibida',{camera_id:id,http:r.status,available:!!cfg.available,has_hls:!!cfg.hls_url,has_whep:!!cfg.whep_url,mode:cfg.mode||'',message:cfg.message||''});if(!r.ok||!cfg.available)throw new Error(cfg.message||'Video en vivo no disponible.');if(typeof PropertyHubWhepPlayer!=='function')throw new Error('El reproductor PropertyHubWhepPlayer no está disponible en este navegador/cache.');player=new PropertyHubWhepPlayer(video);
video.addEventListener('ph-webrtc-state',ev=>{const d=ev.detail||{};if(d.phase==='preference')state.textContent=d.value==='quick-tunnel-hls-first'?'Conexión remota · intentando HLS seguro':(d.value==='mobile-hls-first'?'Dispositivo móvil · intentando HLS seguro':'Navegador de escritorio · intentando WebRTC directo');else if(d.phase==='transport'&&String(d.value).startsWith('hls'))state.textContent='HLS seguro a través del Property Node';else if(d.phase==='webrtc'&&d.value==='fallback-hls')state.textContent='WebRTC no disponible · probando HLS seguro';else if(d.phase==='hls'&&d.value==='fallback-webrtc')state.textContent='HLS no disponible · probando WebRTC';else if(d.phase==='hls')state.textContent='HLS: '+(d.value||'');else if(d.phase==='ice'||d.phase==='peer'||d.phase==='track'||d.phase==='whep'||d.phase==='signaling')state.textContent='WebRTC '+(d.phase||'')+': '+(d.value||'');},{passive:true});
video.addEventListener('ph-webrtc-needs-play',()=>{loading.style.display='none';video.style.display='block';if(playBtn)playBtn.style.display='block';state.textContent='Conectado · toca Reproducir video';},{passive:true});
video.addEventListener('ph-webrtc-error',()=>{state.textContent='Se perdió el video. Puede reintentar.';},{once:true});
const started=await player.start(cfg);clientLog('player-started','Reproducción iniciada',{camera_id:id,transport:started?.transport||cfg.transport||'',needs_user_play:!!started?.needs_user_play});loading.style.display='none';video.style.display='block';if(started?.needs_user_play){if(playBtn)playBtn.style.display='block';state.textContent='Conectado · toca Reproducir video';}else{if(playBtn)playBtn.style.display='none';state.textContent='En vivo · '+String(started?.transport||cfg.transport||'WebRTC').toUpperCase()+' · '+(cfg.codec||'video')+' · '+(cfg.relay_name||'Media Relay');}}catch(err){clientLog('connect-error',String(err?.message||err),{camera_id:id,stack:String(err?.stack||'')});state.textContent='En vivo no disponible: '+(err?.message||err)+'. Mostrando snapshot.';snapshot();}};
modal?.addEventListener('show.bs.modal',e=>{id=Number(e.relatedTarget?.dataset.cameraId||0);wantsLive=String(e.relatedTarget?.dataset.live||'0')==='1';title.textContent=e.relatedTarget?.dataset.cameraName||'Cámara';loadAccess();connect();});modal?.addEventListener('hidden.bs.modal',async()=>{if(player){await player.close();player=null;}video.style.display='none';img.style.display='none';if(playBtn)playBtn.style.display='none';loading.style.display='block';if(accessControls)accessControls.innerHTML='';if(accessBar)accessBar.style.display='none';if(accessState)accessState.textContent='';});playBtn?.addEventListener('click',async()=>{if(!player)return;const ok=await player.requestPlay(true);if(ok){playBtn.style.display='none';state.textContent='En vivo';}});refresh?.addEventListener('click',connect);})();
</script>
